<script setup lang="ts">import type {Pair} from '../types/domain';import {num,pvalue} from '../utils/format';defineProps<{pairs:Pair[];alpha:number}>()</script><template><div class="table-scroll"><table class="pair-table"><thead><tr><th>全部预定义组对</th><th>秩均值差<br/>左−右</th><th>SE / z</th><th>双侧原始p<br/>渐近正态</th><th>Holm p</th><th>α={{alpha}}</th></tr></thead><tbody><tr v-for="p in pairs" :key="p.left_code+p.right_code"><td><b>{{p.left_code}} {{p.left_name}}</b><small>对 {{p.right_code}} {{p.right_name}}</small></td><td>{{num(p.mean_rank_difference,4)}}</td><td>{{num(p.standard_error,4)}}<small>z {{num(p.z,4)}}</small></td><td>{{pvalue(p.p_raw_asymptotic)}}</td><td>{{pvalue(p.p_holm)}}</td><td :class="p.reject?'reject':'muted'">{{p.reject?'拒绝该组对零假设':'未拒绝'}}</td></tr></tbody></table></div></template>